import { Rational } from './rational.ts';
import type { Model, Node, LpResult, BnbResult } from './types.ts';

export function solve(model: Model, limit: number,
  solveLP: (lower: (Rational | null)[], upper: (Rational | null)[], number: number) => LpResult): BnbResult {
  const stack: Node[] = [{lower: model.lower.slice(), upper: model.upper.slice(), depth: 0, parent: null,
    branch: 'root', parentValue: null}];
  const lines: string[] = [];
  const better = (first: Rational, second: Rational): boolean => model.direction === 'maximize' ? first.compare(second) > 0 : first.compare(second) < 0;
  let root: LpResult | null = null;
  let incumbent: {objective: Rational; solution: Rational[]} | null = null;
  let processed = 0;
  let incumbents = 0;
  let pruned = 0;
  let infeasible = 0;
  let cutoff = false;
  let unbounded = false;
  while (stack.length > 0) {
    if (processed === limit) {
      cutoff = true;
      break;
    }
    const node = stack.pop()!;
    const number = ++processed;
    const lp = solveLP(node.lower, node.upper, number);
    if (root === null) root = lp;
    let outcome;
    if (lp.status === 'INFEASIBLE') {
      outcome = 'infeasible';
      infeasible++;
    } else if (lp.status === 'UNBOUNDED') {
      outcome = 'unbounded';
      unbounded = true;
    } else if (incumbent !== null && !better(lp.objective!, incumbent.objective)) {
      outcome = 'pruned';
      pruned++;
    } else {
      const variable = model.integers.find(index => lp.solution![index].d !== 1n);
      if (variable === undefined) {
        incumbent = {objective: lp.objective!, solution: lp.solution!};
        incumbents++;
        outcome = 'incumbent';
      } else {
        const value = lp.solution![variable];
        const floor = new Rational(value.floor());
        const ceil = new Rational(value.ceil());
        const child = {depth: node.depth + 1, parent: number, parentValue: lp.objective};
        const high = {...child, lower: node.lower.slice(), upper: node.upper.slice(), branch: `${model.variables[variable]}>=${ceil}`};
        high.lower[variable] = ceil;
        const low = {...child, lower: node.lower.slice(), upper: node.upper.slice(), branch: `${model.variables[variable]}<=${floor}`};
        low.upper[variable] = floor;
        stack.push(high, low);
        outcome = `branch ${model.variables[variable]} ${value}`;
      }
    }
    const relaxation = lp.status === 'OPTIMAL' ? String(lp.objective) : lp.status.toLowerCase();
    lines.push(`NODE ${number} depth ${node.depth} parent ${node.parent === null ? '-' : node.parent} ` +
      `branch ${node.branch} lp ${relaxation} pivots ${lp.pivots} action ${outcome}`);
    if (unbounded) break;
  }
  const status = unbounded ? 'UNBOUNDED' : cutoff ? 'NODE_LIMIT' : incumbent === null ? 'INFEASIBLE' : 'OPTIMAL';
  let bound = incumbent === null ? null : incumbent.objective;
  if (cutoff) {
    for (let index = stack.length - 1; index >= 0; index--) {
      const node = stack[index];
      lines.push(`OPEN parent ${node.parent} branch ${node.branch} bound ${node.parentValue}`);
      if (bound === null || better(node.parentValue!, bound)) bound = node.parentValue;
    }
  }
  const objective = incumbent === null ? null : incumbent.objective;
  lines.push(`RESULT ${status} objective ${objective === null ? '-' : objective} nodes ${processed} ` +
    `incumbents ${incumbents} pruned ${pruned} infeasible ${infeasible} open ${stack.length} bound ${bound === null ? '-' : bound}`);
  return {status, root, objective, solution: incumbent === null ? null : incumbent.solution, processed, lines};
}

import { readFileSync } from 'node:fs';
import { one, parseNumber } from './rational.ts';
import type { Rational } from './rational.ts';
import type {
  RawModel, RawObjective, RawConstraint, RawBound, ParseSettings, Term, Direction,
} from './types.ts';
const reserved = new Set(['bounds', 'integer', 'binary', 'free', 'inf']);

function fullMatch(pattern: RegExp, text: string | undefined): boolean {
  if (typeof text !== 'string') return false;
  const match = pattern.exec(text);
  return match !== null && match[0].length === text.length;
}

export function isName(text: string | undefined): boolean {
  return fullMatch(/^[a-z][a-z0-9_]*$/, text) && !reserved.has(text);
}

export function number(text: string | undefined, signed = false): Rational | null {
  if (typeof text !== 'string') return null;
  const unsigned = signed && text.startsWith('-') ? text.slice(1) : text;
  if (!fullMatch(/^[0-9]+(?:\.[0-9]+|\/[0-9]+)?$/, unsigned)) return null;
  if (unsigned.includes('/') && BigInt(unsigned.split('/')[1]) === 0n) return null;
  return parseNumber(text);
}

export function expression(items: string[]): Term[] | null {
  let index = 0;
  let sign = 1;
  if (items[index] === '-') {
    sign = -1;
    index++;
  }
  const terms: Term[] = [];
  while (true) {
    const coefficient = number(items[index]);
    if (coefficient !== null && isName(items[index + 1])) {
      terms.push({name: items[index + 1], coefficient: coefficient.multiply(sign)});
      index += 2;
    } else if (isName(items[index])) {
      terms.push({name: items[index], coefficient: one.multiply(sign)});
      index++;
    } else return null;
    if (index === items.length) return terms;
    if (items[index] !== '+' && items[index] !== '-') return null;
    sign = items[index++] === '-' ? -1 : 1;
  }
}

function label(text: string | undefined): string | null {
  return typeof text === 'string' && text.endsWith(':') && isName(text.slice(0, -1)) ? text.slice(0, -1) : null;
}

function objective(items: string[], line: number): RawObjective | null {
  const name = label(items[0]);
  if (items.length < 2 || name === null) return null;
  const terms = expression(items.slice(1));
  return terms === null ? null : {name, terms, line};
}

export function constraint(items: string[], line: number): RawConstraint | null {
  const name = label(items[0]);
  if (items.length < 4 || name === null || !['<=', '>=', '='].includes(items.at(-2)!)) return null;
  const rhs = number(items.at(-1), true);
  const terms = expression(items.slice(1, -2));
  return rhs === null || terms === null ? null : {name, terms, op: items.at(-2)!, rhs, line};
}

function limitValue(text: string | undefined, lower: boolean): {value: Rational | null} | null {
  if (text === (lower ? '-inf' : 'inf')) return {value: null};
  const value = number(text, true);
  return value === null ? null : {value};
}

export function bound(items: string[], line: number): RawBound | null {
  if (items.length === 2 && isName(items[0]) && items[1] === 'free') {
    return {name: items[0], kind: 'both', lower: null, upper: null, line};
  }
  if (items.length === 3 && isName(items[0])) {
    const [name, op, text] = items;
    if (op === '=') {
      const value = number(text, true);
      return value === null ? null : {name, kind: 'both', lower: value, upper: value, line};
    }
    if (op === '>=' || op === '<=') {
      const lower = op === '>=';
      const parsed = limitValue(text, lower);
      return parsed === null ? null : {name, kind: (lower ? 'lower' : 'upper') as 'lower'|'upper', value: parsed.value, line};
    }
  }
  if (items.length === 5 && items[1] === '<=' && items[3] === '<=' && isName(items[2])) {
    const lower = limitValue(items[0], true);
    const upper = limitValue(items[4], false);
    if (lower !== null && upper !== null) return {name: items[2], kind: 'both', lower: lower.value, upper: upper.value, line};
  }
  return null;
}

function parseModel(block: {name: string; body: {text: string; line: number}[]; endLine: number}): RawModel {
  const result: RawModel = {name: block.name, direction: 'maximize', objective: null,
    constraints: [], bounds: [], integers: [], binaries: [], error: null};
  let state = 'A';
  for (const {text, line} of block.body) {
    const items = text.split(' ');
    let accepted = false;
    if (state === 'A') {
      if (text === 'maximize' || text === 'minimize') {
        result.direction = text as Direction;
        state = 'B';
        accepted = true;
      }
    } else if (state === 'B') {
      result.objective = objective(items, line);
      if (result.objective !== null) {
        state = 'C';
        accepted = true;
      }
    } else if (state === 'C') {
      if (text === 'subject to') {
        state = 'D';
        accepted = true;
      }
    } else if (state === 'E' && text === 'bounds') {
      state = 'F';
      accepted = true;
    } else if (['E', 'F'].includes(state) && text === 'integer') {
      state = 'G';
      accepted = true;
    } else if (['E', 'F', 'G'].includes(state) && text === 'binary') {
      state = 'H';
      accepted = true;
    } else if (state === 'D' || state === 'E') {
      const parsed = constraint(items, line);
      if (parsed !== null) {
        result.constraints.push(parsed);
        state = 'E';
        accepted = true;
      }
    } else if (state === 'F') {
      const parsed = bound(items, line);
      if (parsed !== null) {
        result.bounds.push(parsed);
        accepted = true;
      }
    } else if ((state === 'G' || state === 'H') && items.every(isName)) {
      result[state === 'G' ? 'integers' : 'binaries'].push({names: items, line});
      accepted = true;
    }
    if (!accepted) {
      result.error = {line, message: 'syntax error'};
      return result;
    }
  }
  if (['A', 'B', 'C', 'D'].includes(state)) result.error = {line: block.endLine, message: 'syntax error'};
  return result;
}

export function readInputs(): {models: RawModel[]; settings: ParseSettings} {
  const lines = readFileSync('input/models.lp', 'ascii').slice(0, -1).split('\n');
  const models: RawModel[] = [];
  let block: {name: string; body: {text: string; line: number}[]; endLine: number} | null = null;
  for (let index = 0; index < lines.length; index++) {
    const text = lines[index];
    if (text === '' || text.startsWith('#')) continue;
    if (block === null) block = {name: text.split(' ')[1], body: [], endLine: 0};
    else if (text === 'end') {
      block.endLine = index + 1;
      models.push(parseModel(block));
      block = null;
    } else block.body.push({text, line: index + 1});
  }
  const settings: ParseSettings = {logs: new Map<string, number>(), limits: new Map<string, number>(), log_level: 0, node_limit: 0};
  for (const line of readFileSync('input/params.txt', 'ascii').slice(0, -1).split('\n')) {
    const [kind, first, second] = line.split(' ');
    if (kind === 'log') settings.logs.set(first, Number(second));
    else if (kind === 'limit') settings.limits.set(first, Number(second));
    else if (kind === 'log_level') settings.log_level = Number(first);
    else if (kind === 'node_limit') settings.node_limit = Number(first);
  }
  return {models, settings};
}

import { mkdirSync, writeFileSync } from 'node:fs';
import * as parser from './lp_parser.ts';
import {Rational, zero, one, approximate, endpoint} from './rational.ts';
import {Tableau} from './tableau.ts';
import * as simplex from './simplex.ts';
import * as branchBound from './branch_bound.ts';
import type {
  RawModel, Model, ModelConstraint, Term, StandardForm, Column, Mapping,
  StandardRow, LpResult, LpStatus, Counts, ParseSettings, ModelResult, BnbResult,
  Range, Sensitivity, SolveStatus,
} from './types.ts';

function append(target: string[], lines: string[]): void {
  for (const line of lines) target.push(line);
}

function dot(first: Rational[], second: Rational[]): Rational {
  let value = zero;
  for (let index = 0; index < first.length; index++) value = value.add(first[index].multiply(second[index]));
  return value;
}

function coefficients(terms: Term[], variables: string[], indices: Map<string,number>): Rational[] {
  const result = variables.map(() => zero);
  for (const term of terms) {
    const index = indices.get(term.name)!;
    result[index] = result[index].add(term.coefficient);
  }
  return result;
}

function modelData(raw: RawModel): Model {
  if (raw.error !== null) return {
    name: raw.name, direction: raw.direction, variables: [], error: raw.error,
    c: [], constraints: [], lower: [], upper: [], integers: [],
  };
  const variables: string[] = [];
  const indices = new Map<string,number>();
  for (const expression of [raw.objective!, ...raw.constraints]) {
    for (const term of expression.terms) {
      if (!indices.has(term.name)) {
        indices.set(term.name, variables.length);
        variables.push(term.name);
      }
    }
  }
  const model: Model = {name: raw.name, direction: raw.direction, variables, error: null,
    c: coefficients(raw.objective!.terms, variables, indices),
    constraints: raw.constraints.map(constraint => ({...constraint,
      coefficients: coefficients(constraint.terms, variables, indices)})),
    lower: variables.map(() => zero), upper: variables.map(() => null), integers: []};
  const fail = (line: number, message: string): Model => {
    model.error = {line, message};
    return model;
  };
  const inconsistent = (index: number): boolean => {
    const low = model.lower[index], high = model.upper[index];
    return low !== null && high !== null && low.compare(high) > 0;
  };
  const named = new Set<string>();
  for (const constraint of model.constraints) {
    if (named.has(constraint.name)) return fail(constraint.line, `duplicate constraint ${constraint.name}`);
    named.add(constraint.name);
  }
  for (const bound of raw.bounds) {
    if (!indices.has(bound.name)) return fail(bound.line, `unknown variable ${bound.name}`);
    const index = indices.get(bound.name)!;
    if (bound.kind === 'both') {
      model.lower[index] = bound.lower;
      model.upper[index] = bound.upper;
    } else if (bound.kind === 'lower') model.lower[index] = bound.value;
    else model.upper[index] = bound.value;
    if (inconsistent(index)) return fail(bound.line, `inconsistent bounds ${bound.name}`);
  }
  const integral = variables.map(() => false);
  for (const declaration of raw.integers) {
    for (const name of declaration.names) {
      if (!indices.has(name)) return fail(declaration.line, `unknown variable ${name}`);
      const index = indices.get(name)!;
      integral[index] = true;
      if (model.lower[index] !== null) model.lower[index] = new Rational(model.lower[index]!.ceil());
      if (model.upper[index] !== null) model.upper[index] = new Rational(model.upper[index]!.floor());
      if (inconsistent(index)) return fail(declaration.line, `inconsistent bounds ${name}`);
    }
  }
  for (const declaration of raw.binaries) {
    for (const name of declaration.names) {
      if (!indices.has(name)) return fail(declaration.line, `unknown variable ${name}`);
      const index = indices.get(name);
      integral[index] = true;
      model.lower[index] = zero;
      model.upper[index] = one;
    }
  }
  model.integers = variables.map((_, index) => index).filter(index => integral[index]);
  return model;
}

function standardForm(model: Model, lower: (Rational | null)[], upper: (Rational | null)[]): StandardForm {
  const columns: Column[] = [];
  const maps: Mapping[] = [];
  function addVariableColumn(name: string, variable: number, direction: number): number {
    const number = columns.length;
    columns.push({name, variable, direction, artificial: false});
    return number;
  }
  for (let variable = 0; variable < model.variables.length; variable++) {
    const name = model.variables[variable];
    if (lower[variable] !== null) {
      maps.push({kind: 'shift', offset: lower[variable]!, upperRow: null,
        columns: [addVariableColumn(name, variable, 1)]});
    } else if (upper[variable] !== null) {
      maps.push({kind: 'reflect', offset: upper[variable]!, upperRow: null,
        columns: [addVariableColumn(name + "'", variable, -1)]});
    } else {
      maps.push({kind: 'split', offset: zero, upperRow: null,
        columns: [addVariableColumn(name + '+', variable, 1), addVariableColumn(name + '-', variable, -1)]});
    }
  }
  const offsets = maps.map(mapping => mapping.offset);
  const rows: StandardRow[] = model.constraints.map(constraint => ({name: constraint.name, op: constraint.op,
    values: columns.map(column => constraint.coefficients[column.variable!].multiply(column.direction)),
    rhs: constraint.rhs.subtract(dot(constraint.coefficients, offsets)), sigma: 1, slack: null, artificial: null, initial: -1}));
  for (let variable = 0; variable < maps.length; variable++) {
    if (maps[variable].kind !== 'shift' || upper[variable] === null) continue;
    const values = columns.map(() => zero);
    values[maps[variable].columns[0]] = one;
    maps[variable].upperRow = rows.length;
    rows.push({name: model.variables[variable] + '.ub', op: '<=', values,
      rhs: upper[variable]!.subtract(lower[variable]!), sigma: 1, slack: null, artificial: null, initial: -1});
  }
  for (const row of rows) {
    if (row.rhs.n >= 0n) continue;
    row.values = row.values.map(value => value.negate());
    row.rhs = row.rhs.negate();
    row.op = row.op === '<=' ? '>=' : row.op === '>=' ? '<=' : '=';
    row.sigma = -1;
  }
  for (let index = 0; index < rows.length; index++) {
    const row = rows[index];
    if (row.op === '=') continue;
    row.slack = columns.length;
    columns.push({name: 's:' + row.name, variable: null, direction: 0, artificial: false});
    for (let other = 0; other < rows.length; other++) {
      rows[other].values.push(other === index ? one.multiply(row.op === '<=' ? 1 : -1) : zero);
    }
  }
  for (let index = 0; index < rows.length; index++) {
    const row = rows[index];
    if (row.op === '<=') continue;
    row.artificial = columns.length;
    columns.push({name: 'a:' + row.name, variable: null, direction: 0, artificial: true});
    for (let other = 0; other < rows.length; other++) rows[other].values.push(other === index ? one : zero);
  }
  for (const row of rows) row.initial = (row.op === '<=' ? row.slack : row.artificial)!;
  const sign = model.direction === 'minimize' ? 1 : -1;
  const phase1 = columns.map(column => column.artificial ? one : zero);
  const phase2 = columns.map(column => column.variable === null ? zero :
    model.c[column.variable!].multiply(column.direction * sign));
  return {model, lower, upper, columns, maps, rows, phase1, phase2, sign,
    constant: dot(model.c, offsets), artificialCount: columns.filter(column => column.artificial).length};
}

function originalValues(form: StandardForm, values: Rational[], includeOffset = true): Rational[] {
  return form.maps.map(mapping => {
    let value = includeOffset ? mapping.offset : zero;
    for (const column of mapping.columns) value = value.add(values[column].multiply(form.columns[column].direction));
    return value;
  });
}

function solveLP(model: Model, lower: (Rational | null)[], upper: (Rational | null)[], node: number, logLevel: number): LpResult {
  const form = standardForm(model, lower, upper);
  const tableau = new Tableau(form);
  const lines: string[] = [];
  const emit = (level: number, line: string): void => {
    if (level <= logLevel) lines.push(line);
  };
  const phaseLines = (lines_: string[]): void => {
    if (logLevel >= 1) append(lines, lines_);
  };
  const display = (heading: string, costs: Rational[], objective: (value: Rational)=>Rational): void => {
    if (logLevel >= 2) append(lines, tableau.display(heading, costs, objective));
  };
  const objective = (value: Rational): Rational => form.constant.add(value.multiply(form.sign));
  const identity = (value: Rational): Rational => value;
  const result: LpResult = {form, tableau, lines, phase1: 0, phase2: 0, drives: 0, redundant: 0,
    objective: null, solution: null, w: zero, status: 'INFEASIBLE', pivots: 0};
  const finish = (status: LpStatus): LpResult => {
    result.status = status;
    result.pivots = result.phase1 + result.phase2 + result.drives;
    emit(0, `RESULT ${status} objective ${result.objective === null ? '-' : result.objective} ` +
      `phase1 ${result.phase1} phase2 ${result.phase2} drives ${result.drives} redundant ${result.redundant}`);
    return result;
  };
  emit(0, `SOLVE node ${node} rows ${form.rows.length} columns ${form.columns.length} artificials ${form.artificialCount}`);
  for (let variable = 0; variable < model.variables.length; variable++) {
    const mapping = form.maps[variable];
    let line = `MAP ${model.variables[variable]} ${mapping.kind}`;
    if (mapping.kind === 'shift') line += ` ${lower[variable]}` + (upper[variable] === null ? '' : ` upper ${upper[variable]}`);
    else if (mapping.kind === 'reflect') line += ` ${upper[variable]}`;
    emit(1, line);
  }
  for (const row of form.rows) if (row.sigma === -1) emit(1, `FLIP ${row.name}`);
  if (form.artificialCount > 0) {
    emit(1, 'PHASE 1');
    display('phase 1 start', form.phase1, identity);
    const phase = simplex.phase(tableau, form.phase1, form.columns.map((_, index) => index), identity);
    result.phase1 = phase.iterations;
    phaseLines(phase.lines);
    const reduced = tableau.reduced(form.phase1);
    result.w = reduced.value;
    emit(1, `PHASE 1 END objective ${result.w} iterations ${result.phase1}`);
    if (result.w.n > 0n) {
      result.farkas = form.rows.map(row => form.phase1[row.initial].subtract(reduced.costs[row.initial]).multiply(row.sigma));
      display('final', form.phase1, identity);
      return finish('INFEASIBLE');
    }
    for (let row = 0; row < form.rows.length; row++) {
      const leaving = tableau.basis[row];
      if (!form.columns[leaving].artificial) continue;
      const entering = form.columns.findIndex((column, index) => !column.artificial && tableau.T[row][index].n !== 0n);
      if (entering === -1) {
        result.redundant++;
        emit(1, `REDUNDANT row ${form.rows[row].name}`);
      } else {
        emit(1, `DRIVE row ${form.rows[row].name} enter ${form.columns[entering].name} leave ${form.columns[leaving].name}`);
        tableau.pivot(row, entering);
        result.drives++;
      }
    }
  }
  emit(1, 'PHASE 2');
  display('phase 2 start', form.phase2, objective);
  const candidates = form.columns.map((_, index) => index).filter(index => !form.columns[index].artificial);
  const phase = simplex.phase(tableau, form.phase2, candidates, objective);
  result.phase2 = phase.iterations;
  phaseLines(phase.lines);
  if (phase.status === 'unbounded') emit(1, `UNBOUNDED enter ${form.columns[phase.entering!].name}`);
  const value = objective(tableau.reduced(form.phase2).value);
  emit(1, `PHASE 2 END objective ${value} iterations ${result.phase2}`);
  display('final', form.phase2, objective);
  result.solution = originalValues(form, tableau.solution());
  if (phase.status === 'optimal') {
    result.objective = value;
    return finish('OPTIMAL');
  }
  const delta = form.columns.map(() => zero);
  delta[phase.entering!] = one;
  for (let row = 0; row < form.rows.length; row++) delta[tableau.basis[row]] = tableau.T[row][phase.entering!].negate();
  result.ray = originalValues(form, delta, false);
  result.rate = dot(model.c, result.ray);
  return finish('UNBOUNDED');
}

function extrema(values: (Rational | null)[]): string {
  let minimum: Rational | null = null;
  let maximum: Rational | null = null;
  for (const value of values) {
    if (value === null || value.n === 0n) continue;
    const absolute = value.abs();
    if (minimum === null || absolute.compare(minimum) < 0) minimum = absolute;
    if (maximum === null || absolute.compare(maximum) > 0) maximum = absolute;
  }
  return minimum === null ? '- -' : `${minimum} ${maximum}`;
}

function coefficientStatistics(model: Model): string {
  const matrix = model.constraints.flatMap(constraint => constraint.coefficients);
  const nonzeros = matrix.filter(value => value.n !== 0n).length;
  return `STATS nonzeros ${nonzeros} matrix ${extrema(matrix)} objective ${extrema(model.c)} ` +
    `rhs ${extrema(model.constraints.map(constraint => constraint.rhs))} bounds ${extrema(model.lower.concat(model.upper))}`;
}

function shiftedRange(base: Rational, inequalities: [Rational,Rational][]): Range {
  let lower: Rational | null = null;
  let upper: Rational | null = null;
  for (const [current, slope] of inequalities) {
    if (slope.n === 0n) continue;
    const limit = current.negate().divide(slope);
    if (slope.n > 0n) {
      if (lower === null || limit.compare(lower) > 0) lower = limit;
    } else if (upper === null || limit.compare(upper) < 0) upper = limit;
  }
  return [lower === null ? null : base.add(lower), upper === null ? null : base.add(upper)];
}

function basisStatus(form: StandardForm, variable: number, basic: Set<number>): string {
  const mapping = form.maps[variable];
  if (mapping.kind === 'split') return mapping.columns.every(column => !basic.has(column)) ? 'zero' : 'basic';
  const present = basic.has(mapping.columns[0]);
  if (mapping.kind === 'reflect') return present ? 'basic' : 'upper';
  if (!present) return 'lower';
  if (mapping.upperRow !== null && !basic.has(form.rows[mapping.upperRow].slack)) return 'upper';
  return 'basic';
}

function sensitivity(model: Model, root: LpResult): Sensitivity {
  const {form, tableau} = root;
  const reduced = tableau.reduced(form.phase2).costs;
  const basic = new Set(tableau.basis);
  const dual = model.constraints.map((_, index) => reduced[form.rows[index].initial].multiply(-form.sign * form.rows[index].sigma));
  const variableReduced = model.variables.map((_, variable) => {
    let value = model.c[variable];
    for (let row = 0; row < model.constraints.length; row++) {
      value = value.subtract(dual[row].multiply(model.constraints[row].coefficients[variable]));
    }
    return value;
  });
  const coefficientRanges = model.variables.map((_, variable) => {
    const h = form.columns.map(column => column.variable === variable ? one.multiply(form.sign * column.direction) : zero);
    const eta = tableau.reduced(h).costs;
    const inequalities: [Rational,Rational][] = [];
    for (let column = 0; column < form.columns.length; column++) {
      if (!basic.has(column) && !form.columns[column].artificial) inequalities.push([reduced[column], eta[column]]);
    }
    return shiftedRange(model.c[variable], inequalities);
  });
  const rhsRanges = model.constraints.map((constraint, index) => {
    const row = form.rows[index];
    const rho = tableau.T.map(values => values[row.initial].multiply(row.sigma));
    for (let other = 0; other < form.rows.length; other++) {
      if (rho[other].n !== 0n && form.columns[tableau.basis[other]].artificial) return [constraint.rhs, constraint.rhs] as Range;
    }
    return shiftedRange(constraint.rhs, tableau.beta.map((value, other): [Rational,Rational] => [value, rho[other]]));
  });
  let primalDegeneracy = 0;
  for (let row = 0; row < form.rows.length; row++) {
    if (!form.columns[tableau.basis[row]].artificial && tableau.beta[row].n === 0n) primalDegeneracy++;
  }
  let dualDegeneracy = 0;
  for (let column = 0; column < form.columns.length; column++) {
    if (!basic.has(column) && !form.columns[column].artificial && reduced[column].n === 0n) dualDegeneracy++;
  }
  const dualObjective = dot(dual, model.constraints.map(constraint => constraint.rhs)).add(dot(variableReduced, root.solution!));
  return {dual, variableReduced, coefficientRanges, rhsRanges, primalDegeneracy, dualDegeneracy, dualObjective,
    statuses: model.variables.map((_, variable) => basisStatus(form, variable, basic))};
}

function solveModel(model: Model, settings: ParseSettings): ModelResult {
  const counts: Counts = {solves: 0, phase1: 0, phase2: 0, drives: 0};
  if (model.error !== null) return {model, status: 'ERROR', root: null, objective: null, solution: null,
    lines: [`MODEL ${model.name} error`], tree: [], counts, pivots: 0};
  const level = settings.logs.get(model.name) ?? settings.log_level;
  const limit = settings.limits.get(model.name) ?? settings.node_limit;
  const lines: string[] = [`MODEL ${model.name} level ${level}`];
  const solveNode = (lower: (Rational | null)[], upper: (Rational | null)[], number: number): LpResult => {
    const lp = solveLP(model, lower, upper, number, level);
    append(lines, lp.lines);
    counts.solves++;
    counts.phase1 += lp.phase1;
    counts.phase2 += lp.phase2;
    counts.drives += lp.drives;
    return lp;
  };
  let result: BnbResult;
  let tree: string[] = [];
  if (model.integers.length > 0) {
    result = branchBound.solve(model, limit, solveNode);
    tree = [`MODEL ${model.name} ${model.direction} integers ${model.integers.length} node_limit ${limit}`];
    append(tree, result.lines);
  } else {
    const root = solveNode(model.lower, model.upper, 1);
    result = {status: root.status, root, objective: root.objective,
      solution: root!.status === 'OPTIMAL' ? root.solution : null, processed: 1, lines: []};
  }
  return {model, status: result.status, root: result.root, objective: result.objective, solution: result.solution,
    lines, tree, counts, pivots: counts.phase1 + counts.phase2 + counts.drives};
}

function solutionLines(result: ModelResult): string[] {
  const {model, root} = result;
  if (model.error !== null) return [`MODEL ${model.name}`, `STATUS ERROR line ${model.error.line} ${model.error.message}`];
  const lines = [`MODEL ${model.name} ${model.direction} variables ${model.variables.length} ` +
    `constraints ${model.constraints.length} integers ${model.integers.length}`,
  coefficientStatistics(model), `STATUS ${result.status}`];
  if (result.solution !== null) lines.push(`OBJECTIVE ${result.objective} approx ${approximate(result.objective!)}`);
  if (model.integers.length > 0 && root!.status === 'OPTIMAL') {
    lines.push(`RELAXATION ${root.objective} approx ${approximate(root!.objective!)}`);
  }
  if (root!.status === 'INFEASIBLE') {
    lines.push(`INFEASIBILITY ${root!.w}`);
    for (let row = 0; row < root!.form.rows.length; row++) lines.push(`FARKAS ${root!.form.rows[row].name} ${root!.farkas![row]}`);
  }
  if (result.solution !== null || result.status === 'UNBOUNDED') {
    const values = result.solution === null ? root!.solution! : result.solution;
    for (let variable = 0; variable < model.variables.length; variable++) lines.push(`VALUE ${model.variables[variable]} ${values[variable]}`);
  }
  if (result.status === 'UNBOUNDED') {
    for (let variable = 0; variable < model.variables.length; variable++) lines.push(`RAY ${model.variables[variable]} ${root!.ray![variable]}`);
    lines.push(`RATE ${root!.rate!}`);
  }
  if (result.solution !== null) {
    for (const constraint of model.constraints) {
      const value = dot(constraint.coefficients, result.solution);
      const margin = constraint.op === '<=' ? constraint.rhs.subtract(value) : value.subtract(constraint.rhs);
      lines.push(`ROW ${constraint.name} ${value} ${margin}`);
    }
  }
  if (model.integers.length > 0) lines.push(`NODES ${result.counts.solves}`);
  lines.push(`PIVOTS ${result.pivots}`);
  return lines;
}

function sensitivityLines(result: ModelResult): string[] {
  const {model, root} = result;
  if (root === null || root.status !== 'OPTIMAL') return [`MODEL ${model.name} skipped ${root === null ? 'ERROR' : root.status}`];
  const data = sensitivity(model, root);
  const lines = [`MODEL ${model.name} ${model.integers.length === 0 ? 'lp' : 'relaxation'} objective ${root.objective}`,
    'BASIS ' + root.tableau.basis.map(column => root.form.columns[column].name).join(' '),
    `DEGENERACY primal ${data.primalDegeneracy} dual ${data.dualDegeneracy}`, `DUAL objective ${data.dualObjective}`];
  for (let row = 0; row < model.constraints.length; row++) {
    const constraint = model.constraints[row];
    const [lower, upper] = data.rhsRanges[row];
    lines.push(`CONSTRAINT ${constraint.name} price ${data.dual[row]} rhs ${constraint.rhs} range ${endpoint(lower, true)} ${endpoint(upper, false)}`);
  }
  for (let variable = 0; variable < model.variables.length; variable++) {
    const [lower, upper] = data.coefficientRanges[variable];
    lines.push(`VARIABLE ${model.variables[variable]} ${data.statuses[variable]} value ${root!.solution![variable]} ` +
      `reduced ${data.variableReduced[variable]} cost ${model.c[variable]} range ${endpoint(lower, true)} ${endpoint(upper, false)}`);
  }
  return lines;
}

function summaryRow(result: ModelResult): string {
  const objective = result.objective === null ? '-' : String(result.objective);
  const decimal = result.objective === null ? '-' : approximate(result.objective);
  const relaxation = result.root === null || result.root.status !== 'OPTIMAL' ? '-' : String(result.root.objective);
  return [result.model.name, result.status, objective, decimal, relaxation, result.counts.solves, result.pivots].join(',');
}

function main(): void {
  const {models: rawModels, settings} = parser.readInputs();
  const files: Record<string,string[]> = {'iterations.txt': [], 'solutions.txt': [], 'sensitivity.txt': [], 'bnb_tree.txt': [],
    'summary.csv': ['model,status,objective,approx,relaxation,nodes,pivots']};
  const totals: Counts = {solves: 0, phase1: 0, phase2: 0, drives: 0};
  const statuses: Record<SolveStatus,number> = {OPTIMAL: 0, INFEASIBLE: 0, UNBOUNDED: 0, NODE_LIMIT: 0, ERROR: 0};
  let analyzed = 0;
  let integerModels = 0;
  let integerNodes = 0;
  let limited = 0;
  for (const raw of rawModels) {
    const result = solveModel(modelData(raw), settings);
    append(files['iterations.txt'], result.lines);
    append(files['solutions.txt'], solutionLines(result));
    append(files['sensitivity.txt'], sensitivityLines(result));
    append(files['bnb_tree.txt'], result.tree);
    files['summary.csv'].push(summaryRow(result));
    for (const name of Object.keys(totals)) totals[name as keyof Counts] += result.counts[name as keyof Counts];
    statuses[result.status]++;
    if (result.root !== null && result.root.status === 'OPTIMAL') analyzed++;
    if (result.model.error === null && result.model.integers.length > 0) {
      integerModels++;
      integerNodes += result.counts.solves;
      if (result.status === 'NODE_LIMIT') limited++;
    }
  }
  files['iterations.txt'].push(`TOTAL solves ${totals.solves} phase1 ${totals.phase1} phase2 ${totals.phase2} drives ${totals.drives} ` +
    `pivots ${totals.phase1 + totals.phase2 + totals.drives}`);
  files['solutions.txt'].push(`SUMMARY models ${rawModels.length} optimal ${statuses.OPTIMAL} infeasible ${statuses.INFEASIBLE} ` +
    `unbounded ${statuses.UNBOUNDED} node_limit ${statuses.NODE_LIMIT} error ${statuses.ERROR}`);
  files['sensitivity.txt'].push(`SUMMARY analyzed ${analyzed} skipped ${rawModels.length - analyzed}`);
  files['bnb_tree.txt'].push(`SUMMARY models ${integerModels} nodes ${integerNodes} node_limit ${limited}`);
  mkdirSync('output', {recursive: true});
  for (const [name, lines] of Object.entries(files)) writeFileSync(`output/${name}`, lines.join('\n') + '\n', 'ascii');
}

main();

export class Rational {
  n: bigint;
  d: bigint;
  constructor(numerator: string | number | bigint = 0, denominator: string | number | bigint = 1) {
    let n = BigInt(numerator);
    let d = BigInt(denominator);
    if (d < 0n) {
      n = -n;
      d = -d;
    }
    let first = n < 0n ? -n : n;
    let second = d;
    while (second !== 0n) [first, second] = [second, first % second];
    this.n = n / first;
    this.d = d / first;
  }

  static from(value: Rational | string | number | bigint): Rational {
    return value instanceof Rational ? value : new Rational(value);
  }

  add(value: Rational | string | number | bigint): Rational {
    const other = Rational.from(value);
    return new Rational(this.n * other.d + other.n * this.d, this.d * other.d);
  }

  subtract(value: Rational | string | number | bigint): Rational {
    const other = Rational.from(value);
    return new Rational(this.n * other.d - other.n * this.d, this.d * other.d);
  }

  multiply(value: Rational | string | number | bigint): Rational {
    const other = Rational.from(value);
    return new Rational(this.n * other.n, this.d * other.d);
  }

  divide(value: Rational | string | number | bigint): Rational {
    const other = Rational.from(value);
    return new Rational(this.n * other.d, this.d * other.n);
  }

  negate(): Rational {
    return new Rational(-this.n, this.d);
  }

  abs(): Rational {
    return this.n < 0n ? this.negate() : this;
  }

  compare(value: Rational | string | number | bigint): number {
    const other = Rational.from(value);
    const difference = this.n * other.d - other.n * this.d;
    return difference < 0n ? -1 : difference > 0n ? 1 : 0;
  }

  floor(): bigint {
    const quotient = this.n / this.d;
    return this.n < 0n && this.n % this.d !== 0n ? quotient - 1n : quotient;
  }

  ceil(): bigint {
    return -this.negate().floor();
  }

  toString(): string {
    return this.d === 1n ? String(this.n) : `${this.n}/${this.d}`;
  }
}

export const zero = new Rational(0);
export const one = new Rational(1);

export function parseNumber(text: string): Rational {
  if (text.includes('/')) {
    const [numerator, denominator] = text.split('/');
    return new Rational(numerator, denominator);
  }
  if (text.includes('.')) {
    const [whole, decimal] = text.split('.');
    return new Rational(whole + decimal, 10n ** BigInt(decimal.length));
  }
  return new Rational(text);
}

export function approximate(value: Rational): string {
  const numerator = value.n < 0n ? -value.n : value.n;
  const rounded = (2n * numerator * 1000000n + value.d) / (2n * value.d);
  const sign = value.n < 0n && rounded !== 0n ? '-' : '';
  return `${sign}${rounded / 1000000n}.${String(rounded % 1000000n).padStart(6, '0')}`;
}

export function endpoint(value: Rational | null, lower: boolean): string {
  return value === null ? lower ? '-inf' : 'inf' : String(value);
}

import type { Rational } from './rational.ts';
import type { Tableau } from './tableau.ts';
import type { PivotPhase } from './types.ts';

export function phase(tableau: Tableau, costs: Rational[], candidates: number[], objective: (value: Rational) => Rational): PivotPhase {
  const lines: string[] = [];
  let iterations = 0;
  while (true) {
    const reduced = tableau.reduced(costs);
    const entering = candidates.find(column => reduced.costs[column].n < 0n);
    if (entering === undefined) return {status: 'optimal', iterations, lines, entering: null};
    let leaving: number | null = null;
    let ratio: Rational | null = null;
    for (let row = 0; row < tableau.T.length; row++) {
      if (tableau.T[row][entering].n <= 0n) continue;
      const proposed = tableau.beta[row].divide(tableau.T[row][entering]);
      if (leaving === null || proposed.compare(ratio!) < 0 ||
          (proposed.compare(ratio!) === 0 && tableau.basis[row] < tableau.basis[leaving])) {
        leaving = row;
        ratio = proposed;
      }
    }
    if (leaving === null) return {status: 'unbounded', iterations, lines, entering};
    const enteringName = tableau.form.columns[entering].name;
    const leavingName = tableau.form.columns[tableau.basis[leaving]].name;
    const rowName = tableau.form.rows[leaving].name;
    tableau.pivot(leaving, entering);
    iterations++;
    const value = objective(tableau.reduced(costs).value);
    lines.push(`PIVOT ${iterations} enter ${enteringName} reduced ${reduced.costs[entering]} ` +
      `leave ${leavingName} row ${rowName} ratio ${ratio} objective ${value}`);
  }
}

import { zero } from './rational.ts';
import type { Rational } from './rational.ts';
import type { StandardForm } from './types.ts';

export class Tableau {
  form: StandardForm;
  T: Rational[][];
  beta: Rational[];
  basis: number[];
  constructor(form: StandardForm) {
    this.form = form;
    this.T = form.rows.map(row => row.values.slice());
    this.beta = form.rows.map(row => row.rhs);
    this.basis = form.rows.map(row => row.initial);
  }

  reduced(costs: Rational[]): {costs: Rational[]; value: Rational} {
    const reduced = costs.slice();
    let value = zero;
    for (let row = 0; row < this.T.length; row++) {
      const basicCost = costs[this.basis[row]];
      value = value.add(basicCost.multiply(this.beta[row]));
      for (let column = 0; column < reduced.length; column++) {
        reduced[column] = reduced[column].subtract(basicCost.multiply(this.T[row][column]));
      }
    }
    return {costs: reduced, value};
  }

  pivot(row: number, column: number): void {
    const divisor = this.T[row][column];
    this.T[row] = this.T[row].map(value => value.divide(divisor));
    this.beta[row] = this.beta[row].divide(divisor);
    for (let other = 0; other < this.T.length; other++) {
      if (other === row) continue;
      const factor = this.T[other][column];
      this.T[other] = this.T[other].map((value, index) => value.subtract(factor.multiply(this.T[row][index])));
      this.beta[other] = this.beta[other].subtract(factor.multiply(this.beta[row]));
    }
    this.basis[row] = column;
  }

  solution(): Rational[] {
    const values = this.form.columns.map(() => zero);
    for (let row = 0; row < this.basis.length; row++) values[this.basis[row]] = this.beta[row];
    return values;
  }

  display(heading: string, costs: Rational[], objective: (value: Rational) => Rational): string[] {
    const columns = this.form.columns;
    const lines = [`TABLEAU ${heading}`, 'COLUMNS ' + columns.map(column => column.name).join(' ')];
    for (let row = 0; row < this.T.length; row++) {
      lines.push(`ROW ${this.form.rows[row].name} ${columns[this.basis[row]].name} ${this.T[row].join(' ')} | ${this.beta[row]}`);
    }
    const reduced = this.reduced(costs);
    lines.push(`COST ${reduced.costs.join(' ')} | ${objective(reduced.value)}`);
    return lines;
  }
}

